def standard():
    x = Symbol('x')
    h = expand((-42)*x**0+(13)*x**1+(6)*x**2+(-1)*x**3)
    pts = [Integer(-3)] + sorted(set(r for r in solve(h, x) if r.is_real and -3 < r < 7)) + [Integer(7)]
